import{_ as t,o,c as a,ag as r}from"./chunks/framework.HG0H2VLS.js";const u=JSON.parse('{"title":"Listing Screen — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/cc/templates/ListingScreen/ListingScreen.figma-notes.md","filePath":"public/demos/src/cc/templates/ListingScreen/ListingScreen.figma-notes.md"}'),s={name:"public/demos/src/cc/templates/ListingScreen/ListingScreen.figma-notes.md"};function i(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="listing-screen-—-figma-notes" tabindex="-1">Listing Screen — Figma Notes <a class="header-anchor" href="#listing-screen-—-figma-notes" aria-label="Permalink to &quot;Listing Screen — Figma Notes&quot;">​</a></h1><p>Tier: <strong>Template</strong> · Product area: <strong>Control Centre / Listing Screens</strong> Built 2026-09-17 (Pass 1 — Default view).</p><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>File key</td><td><code>Lus07xi8pPXLN87sQIyrEt</code> (Affino — Design System)</td></tr><tr><td>Page</td><td><code>3644:125909</code> — &quot;Listings&quot;</td></tr><tr><td>Built this pass</td><td><code>3645:148870</code> (Default · Desktop) · <code>3648:161126</code> (Default · Mobile)</td></tr><tr><td>Datatable type</td><td><code>3648:164786</code> (Orders · Desktop · Scroll) · <code>3648:164467</code> (Orders · Mobile · Trigger)</td></tr><tr><td>Shell</td><td><code>3644:127733</code> — &quot;CC Shell&quot; (shared with ControlScreen)</td></tr></tbody></table><h2 id="why-this-template-exists" tabindex="-1">Why this template exists <a class="header-anchor" href="#why-this-template-exists" aria-label="Permalink to &quot;Why this template exists&quot;">​</a></h2><p>Roughly <strong>400 Control Centre screens</strong> are this one layout. They differ in only two things: which <strong>datatable Type</strong> renders, and which <strong>default filters</strong> show. Both are config (<code>listing-data.js</code>), not markup — so a new screen is a new config entry, not a new template.</p><h2 id="variant-matrix" tabindex="-1">Variant matrix <a class="header-anchor" href="#variant-matrix" aria-label="Permalink to &quot;Variant matrix&quot;">​</a></h2><p>The Listings page holds 19 screen frames in three rows. Pass 1 built row 1 only; the rest are the interaction set and are deliberately deferred (designer&#39;s scoping call, 2026-09-17 — &quot;build the screen … then we can work through all of the functionality&quot;).</p><table tabindex="0"><thead><tr><th>#</th><th>Screen</th><th>Desktop</th><th>Mobile</th><th>Status</th></tr></thead><tbody><tr><td>1</td><td>Default</td><td><code>3645:148870</code></td><td><code>3648:161126</code></td><td><strong>Built</strong></td></tr><tr><td>2</td><td>Filter Active</td><td><code>3645:148871</code></td><td><code>3650:166012</code></td><td>Pass 2</td></tr><tr><td>3</td><td>Wrapping + Multiple Filters</td><td><code>3645:151046</code></td><td><code>3650:167527</code></td><td>Pass 2</td></tr><tr><td>4</td><td>View Dropdown</td><td><code>3645:153953</code></td><td><code>3650:168587</code></td><td>Pass 2</td></tr><tr><td>5</td><td>New View</td><td><code>3645:156799</code></td><td><code>3650:169668</code></td><td>Pass 2</td></tr><tr><td>6</td><td>Save View</td><td><code>3645:155718</code></td><td><code>3650:170677</code></td><td>Pass 2</td></tr><tr><td>7</td><td>Actions Menu</td><td><code>3645:157810</code></td><td><code>3650:171678</code></td><td>Pass 2</td></tr><tr><td>8</td><td>Datatable Expanded</td><td><code>3645:158905</code></td><td><code>3650:173002</code></td><td>Pass 2</td></tr><tr><td>9</td><td>Filter Dropdown / Text</td><td><code>3664:13374</code></td><td>—</td><td>Pass 2</td></tr><tr><td>10</td><td>Filter Dropdown / Select</td><td><code>3664:14458</code></td><td>—</td><td>Pass 2</td></tr><tr><td>11</td><td>Filter Dropdown / More Filters</td><td><code>3664:15491</code></td><td>—</td><td>Pass 2</td></tr></tbody></table><p>Note: much of rows 2–11 already exists in the <strong>FilterBar</strong> pattern, which was built from this same page. Pass 2 is finishing and wiring it, not building it cold.</p><h2 id="template-shell-—-paint-values-skill-step-3a" tabindex="-1">Template shell — paint values (skill Step 3a) <a class="header-anchor" href="#template-shell-—-paint-values-skill-step-3a" aria-label="Permalink to &quot;Template shell — paint values (skill Step 3a)&quot;">​</a></h2><p>Every value below traces to a <code>get_design_context</code> fetch, not to intuition.</p><table tabindex="0"><thead><tr><th>Wrapper</th><th>Property</th><th>Figma binding</th><th>Applied</th></tr></thead><tbody><tr><td>Page ground</td><td>background</td><td><code>--cc-ui-primary-bg</code></td><td><code>.cc-control__page</code> (ControlScreen, reused)</td></tr><tr><td>Page content</td><td>padding</td><td><code>--ai-spacing-6</code> (24px)</td><td><code>.cc-control__page</code> — already correct, not overridden</td></tr><tr><td>Content column (&quot;Frame 1&quot;)</td><td>flex-direction</td><td>column</td><td><code>.cc-listing</code></td></tr><tr><td>Content column</td><td>gap</td><td><code>--ai-spacing-4</code> (12px)</td><td><code>.cc-listing</code></td></tr><tr><td>Chrome — top nav</td><td>background</td><td><code>--cc-header-primary-bg</code></td><td>TopNavigation (reused)</td></tr><tr><td>Chrome — header band</td><td>background</td><td><code>--cc-header-secondary-bg</code></td><td><code>.cc-header</code> (reused)</td></tr><tr><td>Chrome — header band</td><td>min-height / padding</td><td><code>--ai-spacing-11</code> / <code>--ai-spacing-5</code></td><td><code>.cc-header</code> — already correct</td></tr><tr><td>Header title</td><td>font / size / tracking</td><td><code>--ai-font-title</code> bold · <code>--ai-font-fixed-xl</code> · <code>--ai-tracking-3</code></td><td><code>.cc-header__title</code> — already correct</td></tr></tbody></table><p>The shell is <strong>not forked</strong>. In Figma, ControlScreen and every listing screen are instances of the same <code>CC Shell</code> component, so <code>ControlScreen.css</code> is linked and its <code>.cc-control__*</code> classes are reused — the same approach SeatingPlanner takes.</p><p><code>.cc-control__page</code> already supplies the <code>cs-page</code> container context and <code>isolation: isolate</code>, so an open FilterBar dropdown paints above the table for free.</p><h2 id="the-header-is-a-contextual-override" tabindex="-1">The header is a contextual override <a class="header-anchor" href="#the-header-is-a-contextual-override" aria-label="Permalink to &quot;The header is a contextual override&quot;">​</a></h2><p><code>get_design_context</code> on the Chrome instance returns the CC Shell component&#39;s <strong>default</strong> header — avatar, user details, Logout / View Site. The rendered frame shows <strong>none of it</strong>: just the title &quot;Orders&quot;. The screenshot is authoritative. Built as a title-only <code>.cc-header--control</code>, which needed no new CSS, only fewer children.</p><p>This is worth remembering for the other ~400 screens: the listing header is always a bare title.</p><h2 id="token-gaps-and-figma-side-slips" tabindex="-1">Token gaps and Figma-side slips <a class="header-anchor" href="#token-gaps-and-figma-side-slips" aria-label="Permalink to &quot;Token gaps and Figma-side slips&quot;">​</a></h2><p>All three were raised as STOPs and resolved by the designer on 2026-09-17.</p><table tabindex="0"><thead><tr><th>#</th><th>Finding</th><th>Where</th><th>Resolution</th></tr></thead><tbody><tr><td>1</td><td><code>--spacing-5</code> <strong>primitive</strong> (not <code>--ai-spacing-5</code>) bound to the ORDER NO header + body cells</td><td><code>3648:164918</code>, every ORDER NO cell</td><td>Normalise to <code>--ai-spacing-5</code>. <strong>Figma still needs fixing.</strong></td></tr><tr><td>2</td><td>Raw <code>px-[12px] py-[8px] gap-[8px]</code> — unbound — on the ACCOUNT CODE / QTY / ORDER TOTAL header cells, where the other three headers bind <code>--ai-spacing-5</code> / <code>--ai-spacing-2</code></td><td><code>3648:164936/164942/164948</code></td><td>Normalise all six to <code>--ai-spacing-5</code> / <code>--ai-spacing-2</code>. This also removed a real 4px header/body misalignment visible in the design. <strong>Figma still needs fixing.</strong></td></tr><tr><td>3</td><td>Mobile customer role bound to raw <code>12px</code></td><td><code>3648:164504</code></td><td>Normalise to <code>--ai-font-fixed-xxs</code>. <strong>Figma still needs fixing.</strong></td></tr></tbody></table><p>Mobile header tracking is a raw <code>0.6px</code>; that is <code>--ai-tracking-7</code> (0.05em) at the 11px font size, so the token is used. Letter-spacing is in any case a documented raw-px exception.</p><h2 id="contextual-overrides-case-b" tabindex="-1">Contextual overrides (Case B) <a class="header-anchor" href="#contextual-overrides-case-b" aria-label="Permalink to &quot;Contextual overrides (Case B)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Base component</th><th>Override</th><th>Why not a variant</th></tr></thead><tbody><tr><td>Account chip</td><td><code>btn btn--tertiary btn--sm</code></td><td><code>border-color: var(--ai-border-secondary)</code></td><td>Tertiary&#39;s own border token is transparent in every mode. Designer&#39;s call: scope it, don&#39;t add a Button variant.</td></tr><tr><td>Initials avatar</td><td><code>avatar avatar--initials</code></td><td>brand palette (<code>--ai-surface-brand-soft-extra</code> / <code>--ai-text-brand</code>)</td><td>The Avatar component&#39;s own <code>--initials</code> is the <strong>info</strong> palette. Applied by analogy with the chip; flagged for the designer to formalise if it turns out to be house style.</td></tr></tbody></table><h2 id="column-widths-are-intrinsic-not-the-figma-pixels" tabindex="-1">Column widths are intrinsic, not the Figma pixels <a class="header-anchor" href="#column-widths-are-intrinsic-not-the-figma-pixels" aria-label="Permalink to &quot;Column widths are intrinsic, not the Figma pixels&quot;">​</a></h2><p>Figma fixes ORDER NO 114, QTY 100, kebab 48, checkbox 32, and min-widths of 250 (CUSTOMER) / 170 (ACCOUNT). None maps to an <code>--ai-*</code> token, so writing them would breach the hardcoded-dimension rule. <code>.datatables__col--hug</code> shrink-wraps the narrow columns and the wide ones absorb the remainder — same visual result, and it holds at every width, which matters because the content column resizes with no window resize (CLAUDE.md §4a).</p><h2 id="responsive" tabindex="-1">Responsive <a class="header-anchor" href="#responsive" aria-label="Permalink to &quot;Responsive&quot;">​</a></h2><p>Container queries only — no <code>matchMedia</code>, no viewport media query. Mobile keeps <strong>ORDER + CUSTOMER</strong>; the other four columns move into the kebab detail row, which the renderer builds from the same column list that produced the header, so the two cannot drift.</p><p>Measured at 390px viewport (in-shell, not the component&#39;s own 384px canvas): content column 338px → datatable 275px → table 273px, <code>scrollWidth === clientWidth</code>, no overflow.</p><p>Two fixes were needed to get there, both found by measuring rather than eyeballing:</p><ol><li>The row-edit button was built as <code>btn--icon</code> (40px). Figma&#39;s node is <code>2926:3566</code> — the Secondary <code>Icon Only=True, Size=xs</code> variant, i.e. the stock <strong><code>btn--icon btn--xs</code></strong> (24×24). The wrong size cost 28px and pushed the kebab column off-screen.</li><li>The mobile kebab cell needed <code>padding-inline: var(--ai-spacing-0)</code> per Figma. The first attempt silently lost the cascade: <code>.datatables--orders td.&lt;class&gt;</code> is (0,2,1) against the blanket cell rule&#39;s (0,2,2) — equal class count, more elements, so the blanket rule won. <code>.table</code> was added to the selector to lift it to (0,3,1).</li></ol><p>Figma also shortens the ORDER NO header to &quot;Order&quot; on mobile. CSS cannot swap text and JS must not read a container query, so both strings are rendered and the container query picks one (<code>.datatables__label--full</code> / <code>--short</code>).</p><h2 id="demo-chrome-no-theme-cog-on-this-screen" tabindex="-1">Demo chrome: no theme cog on this screen <a class="header-anchor" href="#demo-chrome-no-theme-cog-on-this-screen" aria-label="Permalink to &quot;Demo chrome: no theme cog on this screen&quot;">​</a></h2><p>This template loads <strong><code>src/styles/theme-param.js</code></strong>, not <code>src/components/dark-mode-toggle.js</code> — the only CC screen that does.</p><p>Both apply the saved theme from <code>&lt;head&gt;</code> before first paint, using the same <code>demo-theme</code> localStorage key, so the light/dark choice still follows a visitor here from any other page. The difference is that <code>dark-mode-toggle.js</code> also injects the <strong>demo toolbar</strong> — the fixed gear tab pinned to the right edge. Dropped at the designer&#39;s request (2026-09-17): this template is the shell for ~400 real Control Centre screens, and a demo affordance floating over it reads as part of the product rather than as demo furniture.</p><p>The in-product control is unaffected — the <strong>User Menu dropdown still carries its ThemeToggle</strong> (Figma HeaderGroup <code>4146:6685</code>), driven by <code>ThemeToggle.js</code>. That is the real light/dark switch for this surface; only the demo tab is gone.</p><p>Other CC screens keep their cog; nothing shared was changed.</p><h2 id="page-padding-and-the-scrollbar-gutter" tabindex="-1">Page padding and the scrollbar gutter <a class="header-anchor" href="#page-padding-and-the-scrollbar-gutter" aria-label="Permalink to &quot;Page padding and the scrollbar gutter&quot;">​</a></h2><p><code>.cc-control__page</code> scrolls and sets <code>scrollbar-gutter: stable</code>, which reserves a 15px gutter on the <strong>end edge only</strong>. ControlScreen compensates by trimming <code>padding-right</code> at both breakpoints, so the content sits evenly against it.</p><table tabindex="0"><thead><tr><th>Breakpoint</th><th>padding L</th><th>padding R</th><th>+ gutter</th><th>visual L / R</th></tr></thead><tbody><tr><td>Desktop (≥768)</td><td><code>--ai-spacing-6</code> (24)</td><td><code>--ai-spacing-4</code> (12)</td><td>15</td><td>24 / 27</td></tr><tr><td>Mobile (≤767)</td><td><code>--ai-spacing-4</code> (12)</td><td><code>--ai-spacing-0</code> (0)</td><td>15</td><td>12 / 15</td></tr></tbody></table><p>The mobile row was <code>--ai-spacing-2</code> (6px) until 2026-09-17, which read as <strong>12 / 21</strong> — a 9px lean, three times the desktop tolerance, and present on every CC screen rather than just this one. Fixed in <code>ControlScreen.css</code> so all of them benefit.</p><p><strong>Exactly even is not reachable by trimming at mobile</strong>: the reserved gutter (15px) is already wider than the 12px left padding, so the only symmetric option is <code>scrollbar-gutter: stable both-edges</code>, which costs 15px of content on each side of a 390px screen. Deliberately not taken.</p><p><strong>Do not re-declare <code>padding</code> on <code>.cc-control__page--listing</code>.</strong> It has the same specificity as <code>.cc-control__page</code> but loads later, so a shorthand there wins and silently restores the untrimmed right padding — which is exactly how the 39px right gap arose on 2026-09-17.</p><h2 id="filter-pickers-—-which-dropdown-each-chip-opens-2026-09-17" tabindex="-1">Filter pickers — which dropdown each chip opens (2026-09-17) <a class="header-anchor" href="#filter-pickers-—-which-dropdown-each-chip-opens-2026-09-17" aria-label="Permalink to &quot;Filter pickers — which dropdown each chip opens (2026-09-17)&quot;">​</a></h2><p>Figma <code>3681:99951</code> (&quot;Filter Dropdown / Options&quot;) shows a chip&#39;s picker anchored under it. The assignment per filter is the designer&#39;s (2026-09-17), and every Type is <strong>already built</strong> in <code>src/patterns/FilterDropdowns/</code> — nothing new was drawn or written for this screen.</p><table tabindex="0"><thead><tr><th>Filter</th><th>Asked for</th><th>FilterDropdowns Type</th><th>Node</th><th><code>type</code> in config</th></tr></thead><tbody><tr><td>Customer</td><td>selection options w/subset</td><td>Select Options w/subtext</td><td><code>3039:5628</code></td><td><code>select-options</code></td></tr><tr><td>User Code</td><td>predictive text</td><td>Predictive Text Options</td><td><code>3039:5625</code></td><td><code>predictive</code></td></tr><tr><td>Account</td><td>multi select</td><td>Multi Select</td><td><code>3039:5629</code></td><td><code>multi-select</code></td></tr><tr><td>Account Code</td><td>predictive text</td><td>Predictive Text Options</td><td><code>3039:5625</code></td><td><code>predictive</code></td></tr><tr><td>Order No.</td><td>text</td><td>Text</td><td><code>3039:5633</code></td><td><code>text</code></td></tr><tr><td>Add Filters</td><td>more filters</td><td>More Filters</td><td><code>3039:5637</code></td><td><code>more-filters</code></td></tr></tbody></table><p>Two notes on the mapping:</p><ul><li><strong>&quot;w/subset&quot; → w/subtext.</strong> Figma has no &quot;subset&quot; type; <code>Select Options w/subtext</code> is the one that renders a name plus a secondary line, which is what the Customer rows need (name + account · code). Read as a typo.</li><li><strong>Plain <code>Predictive Text</code> (<code>3039:5638</code>) does not exist in code.</strong> The pattern consolidated it into <code>Predictive Text Options</code> on the grounds that predictive always reveals options — so both predictive filters get that Type.</li></ul><p><strong>It is config, not markup.</strong> Each filter in <code>listing-data.js</code> names its <code>type</code>; <code>ListingScreen.js</code> <code>FILTER_PANELS</code> maps that to the pattern&#39;s markup. Assigning a different picker to a filter is a one-word change, which is what makes this survivable across ~400 screens.</p><h3 id="initialisation-order" tabindex="-1">Initialisation order <a class="header-anchor" href="#initialisation-order" aria-label="Permalink to &quot;Initialisation order&quot;">​</a></h3><p>The chips are rendered by <code>ListingScreen.js</code> on <code>DOMContentLoaded</code>, which is <strong>after</strong> <code>FilterItem.js</code> and <code>FilterDropdowns.js</code> have already auto-initialised whatever was in the static markup. The rendered nodes would therefore be inert. <code>ListingScreen.js</code> dispatches <code>listing:rendered</code> and a module listener re-initialises — <strong>scoped to the new nodes</strong>, because <code>FilterItem.init</code> has no idempotency guard and re-running it over the document would bind every existing chip twice. (<code>FilterDropdowns</code> does guard, via <code>__filterDropdowns</code>.)</p><p><code>Type=More Filters</code> carries no <code>data-filter-dropdowns</code> attribute and is not initialised — correct, not a miss: it is chips only, with no select, predictive, search or apply behaviour. The pattern&#39;s own demo has it the same way.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>ListingScreen.html</code></td><td>Full screen. Shell copied from ControlScreen (same Figma component); page content is the listing.</td></tr><tr><td><code>ListingScreen.css</code></td><td>Only the content column. 63 lines — everything else is reused.</td></tr><tr><td><code>ListingScreen.js</code></td><td>Config-driven renderer: thead, tbody, detail rows, pagination.</td></tr><tr><td><code>listing-data.js</code></td><td>Column config + default filters + rows + paging. <strong>The swap point for real data.</strong></td></tr><tr><td><code>Datatables.css</code></td><td><code>.datatables--orders</code> lives with its component, since Type=Orders is a Datatables variant.</td></tr></tbody></table><h2 id="backend-handover" tabindex="-1">Backend handover <a class="header-anchor" href="#backend-handover" aria-label="Permalink to &quot;Backend handover&quot;">​</a></h2><p>Markers: <code>listing-default-filters</code>, <code>listing-export</code>, <code>listing-orders-rows</code>. Contract sketch in <code>listing-data.js</code>; rows are shaped from the live <code>/control/orders</code> screen so the mapping is one-to-one. See HANDOVER.md.</p><h2 id="still-open" tabindex="-1">Still open <a class="header-anchor" href="#still-open" aria-label="Permalink to &quot;Still open&quot;">​</a></h2><ul><li><strong>Pass 2</strong>: filter dropdowns, apply/clear, sort, paging, the view menus, row expand.</li><li><strong>Figma fixes</strong>: the three binding slips above.</li><li><strong>Mobile frame <code>3648:161126</code> is titled &quot;Articles&quot;</strong>, not &quot;Orders&quot; — stale title on the designer&#39;s side. Built as &quot;Orders&quot; to match the desktop frame and the live screen.</li><li><strong>Pagination active state</strong>: Figma paints it <code>--ai-datatable-table-footer-bg</code>, which in CC <strong>light</strong> resolves to the same white as the pagination container — so weight alone carries the state. <code>aria-current=&quot;page&quot;</code> is set, but this is a contrast question for the designer, not something to &quot;fix&quot; in code.</li></ul><h2 id="filter-selection-add-filters-pass-2b" tabindex="-1">Filter selection + Add Filters (pass 2b) <a class="header-anchor" href="#filter-selection-add-filters-pass-2b" aria-label="Permalink to &quot;Filter selection + Add Filters (pass 2b)&quot;">​</a></h2><ul><li><strong>Account starts fully deselected.</strong> Its chip therefore renders Default, and ticking 1–3 boxes lists them, 4+ rolls up to <code>&lt;first&gt;, and N more</code> — the rollup is FilterItem&#39;s, not this screen&#39;s (see FilterBar notes).</li><li><strong>Add Filters moves a facet onto the bar.</strong> <code>LISTING_ORDERS_MORE_FILTERS</code> is now a list of full filter configs rather than bare names, because a chosen facet needs the same <code>type</code>/<code>options</code> as a default filter to open a working dropdown. <code>init()</code> works on a shallow copy of both filter arrays so <code>LISTING_SCREENS</code> still describes a <em>fresh</em> screen afterwards.</li><li><strong><code>FilterDropdownItem.js</code> must be loaded.</strong> It carries the option rows&#39; click handler; FilterDropdowns.js does not. Without it the pickers open and nothing can be selected, silently.</li></ul><h3 id="open-with-the-designer" tabindex="-1">Open with the designer <a class="header-anchor" href="#open-with-the-designer" aria-label="Permalink to &quot;Open with the designer&quot;">​</a></h3><p>The five default filters have assigned dropdown types (Customer = Selection Options, User Code / Account Code = Predictive, Account = Multi Select, Order No. = Text). The nine More Filters facets have <strong>not</strong> been assigned one, so each carries <code>type: &#39;text&#39;</code> — the only type needing no invented option list. Three clearly want a date picker, which FilterDropdowns already provides (Date Range / Date In the last / Date Equal To) but this screen does not yet build; the status/method/type facets want Multi Select once their real option lists are known. Each is a one-word change in <code>listing-data.js</code>.</p><h2 id="table-filtering-pass-2c" tabindex="-1">Table filtering (pass 2c) <a class="header-anchor" href="#table-filtering-pass-2c" aria-label="Permalink to &quot;Table filtering (pass 2c)&quot;">​</a></h2><p>Front-end filtering over the mock rows, so the screen is demonstrable before a backend exists. <code>TODO(backend:Listing)</code> in <code>listing-data.js</code> marks the seam: the real <code>/control/orders</code> filters server-side and returns the counts with the rows, at which point <code>field</code> becomes the query-parameter name and <code>applyFilters()</code> goes away.</p><p><strong>Config, not code.</strong> Each filter carries a <code>field</code> naming the row property it tests (<code>customer.name</code> walks into the object), so nothing in the renderer knows an Orders column from a Contacts one.</p><table tabindex="0"><thead><tr><th>Filter</th><th>Type</th><th>Field</th><th>Match</th></tr></thead><tbody><tr><td>Customer</td><td>Selection Options</td><td><code>customer.name</code></td><td>exact, any of</td></tr><tr><td>User Code</td><td>Text</td><td><code>userCode</code></td><td>contains</td></tr><tr><td>Account</td><td>Multi Select</td><td><code>account</code></td><td>exact, any of</td></tr><tr><td>Account Code</td><td>Text</td><td><code>accountCode</code></td><td>contains</td></tr><tr><td>Order No.</td><td>Text</td><td><code>orderNo</code></td><td>contains</td></tr></tbody></table><p>A <strong>Text</strong> filter is a search — one typed fragment, matched loosely. Every other type is a pick-list whose values came from the row data itself, so they match exactly, and several picks mean &quot;any of these&quot;. Filters combine with AND.</p><p><code>User Code</code> and <code>Account Code</code> were Predictive; the designer moved both to plain Text on 2026-09-17. <code>userCode</code> has no column — it exists only so that filter has something to test.</p><p><strong>Values arrive by event, not by reading the chip.</strong> <code>FilterItem</code>&#39;s label rolls 4+ values up into <code>&lt;first&gt;, and 3 more</code>, which is lossy, so the bar announces <code>filter-bar:change</code> (<code>{ name, values }</code>) on every commit and clear.</p><p><strong>A field-less filter is not active.</strong> It cannot narrow the table, so it must also not make the footer report a count it did not produce — the nine More Filters facets are all in that position until they get types and fields.</p><h3 id="empty-state-—-flagged" tabindex="-1">Empty state — flagged <a class="header-anchor" href="#empty-state-—-flagged" aria-label="Permalink to &quot;Empty state — flagged&quot;">​</a></h3><p><code>TODO(design:Listing)</code>: <strong>Datatables has no empty state in Figma.</strong><code>.cc-listing__empty</code> mirrors EventPicker&#39;s <code>Type=Event Picker (no results)</code> (3108:6659) token for token, that being the established treatment on the CC surface, rather than inventing a second one. It wants a Datatables variant of its own.</p><p>Note the cell keeps table display and the flex column is a <code>div</code> inside it: a <code>&lt;td&gt;</code> set to <code>display: flex</code> leaves table layout and then ignores its own <code>colspan</code>, collapsing the empty state into the first column.</p><h2 id="saved-views-pass-2d" tabindex="-1">Saved views (pass 2d) <a class="header-anchor" href="#saved-views-pass-2d" aria-label="Permalink to &quot;Saved views (pass 2d)&quot;">​</a></h2><p>A view IS a filter set: which filters are on the bar, in what order, holding what values. FilterBar owns the list and its rows; the screen owns what a row MEANS, so snapshots live here in a <code>WeakMap</code> keyed by the row element.</p><ul><li><strong>Save view</strong> → names the view → the snapshot is taken and the row selected.</li><li><strong>Selecting</strong> a view restores its snapshot: the filter list, the More Filters remainder, and every value. Chips are rebuilt (this is the one case where a full chip re-render is right) with their pickers already showing the restored state — ticked checkboxes, filled fields, selected option rows — which is why the panel builders take the values.</li><li>A row with <strong>no snapshot</strong> — the shipped mock views, or a brand-new empty one — stands for the unfiltered listing.</li><li>After restoring, <code>bar.resetSaveView(values)</code> re-baselines, so the Save view CTA is not owed. Change something and it returns; undo the change and it goes again.</li></ul><p>The bar establishes its baseline before these chips exist, so the screen also calls <code>resetSaveView</code> after the FIRST render — otherwise the bar reads the initial chips as a change and offers to save the view it just opened on.</p><p>TODO(backend:Listing): in memory, like the rest of the saved-views mocking. → <code>POST /control/orders/views { name, filters:[{name,values}] }</code> and <code>GET /control/orders/views</code>.</p><p>Also fixed here: FilterBar&#39;s empty-view rule hid <code>.filter-bar__chips &gt; .filter-item</code>, but a chip with a picker is WRAPPED in <code>.filter-bar__chip</code>, so the listing&#39;s chips stayed visible in an empty view. The wrapper now carries <code>.filter-bar__chip--add</code> so the rule can spare the Add Filters chip.</p><h2 id="search-pass-2e" tabindex="-1">Search (pass 2e) <a class="header-anchor" href="#search-pass-2e" aria-label="Permalink to &quot;Search (pass 2e)&quot;">​</a></h2><p>Free text narrows the table alongside the chips — a search inside a filtered view searches that view, not the whole listing. The threshold lives in FilterBar; the screen just reacts to <code>filter-bar:search</code>.</p><p><strong>What it looks at is derived from the COLUMN config, not the row object.</strong> Scanning the row would match things the table never shows: every row would be a hit for &quot;photos&quot;, because that is in the avatar URL. So <code>searchableText()</code> walks the columns and reads <code>text</code> / <code>chip</code> values plus a <code>user</code> cell&#39;s name and role.</p><p>By the same rule the hidden <code>userCode</code> is <strong>not</strong> searchable — it is not on screen, and it has its own filter chip. Worth a check with the designer if the expectation is that search reaches fields the listing does not display.</p><p><strong>Search is not part of a saved view</strong>, and survives switching between them: a view is a filter set, and the search is a transient look inside whichever view is open. It therefore does not make the Save view CTA appear either.</p><h2 id="real-orders-schema-pass-3" tabindex="-1">Real Orders schema (pass 3) <a class="header-anchor" href="#real-orders-schema-pass-3" aria-label="Permalink to &quot;Real Orders schema (pass 3)&quot;">​</a></h2><p>Columns and filters are now the live screen&#39;s, read from the Affino source (client_key Comrz). Provenance is recorded at the top of <code>listing-data.js</code>. Mark, 2026-09-18: replicate the DATA; the presentation and interaction move to the new design system — &quot;that is the task&quot;.</p><h3 id="what-is-a-reproduction" tabindex="-1">What is a reproduction <a class="header-anchor" href="#what-is-a-reproduction" aria-label="Permalink to &quot;What is a reproduction&quot;">​</a></h3><ul><li><strong>20 data columns</strong> from <code>OrderProcessingDef.cfm</code> (<code>CProperties</code>, rows flagged <code>l</code>), plus Account / Account Code which are present on the standalone screen and suppressed only when embedded on an account record.</li><li><strong>Seven sortable columns</strong>, the explicit <code>hs</code> whitelist from <code>OrderProcessings.cfm</code>: <code>OrderNo.</code> <code>Date</code> <code>Customer</code> <code>Account</code> <code>Value</code><code>Status</code> <code>PaymentStatus</code>. Everything else silently falls through, so Qty, Order Total and Tax carry no sort control however sortable they look. Default <code>Date</code> descending.</li><li><strong>Six default filters</strong> — the live &quot;Simple Search&quot; form. Customer and Order Owner are autocompletes (→ Predictive); User Code, Account, Account Code and Order No. are plain text. Customer and User Code are DIFFERENT fields shown at once, as are Account and Account Code.</li><li><strong>47 advanced filters</strong> with their real widget types and, where the source defines them statically, their real option lists (Order Status ×16, Payment Status ×3, Order Type ×2, Sub Order Type ×7, Order Method ×2 …). DB-lookup option VALUES are mock; the names and types are not.</li><li><code>TaxRule</code> is deliberately absent — accepted by the controller and used in the query, but no form renders a control for it. Building one would be inventing UI.</li></ul><h3 id="what-is-new-and-says-so" tabindex="-1">What is new, and says so <a class="header-anchor" href="#what-is-new-and-says-so" aria-label="Permalink to &quot;What is new, and says so&quot;">​</a></h3><ul><li><strong>The chip bar.</strong> The live screen swaps a Simple form for an Advanced one behind a <code>+</code>; it has no default-chips / Add-Filters model.</li><li><strong>The search field.</strong> The live <code>Search</code> param is an <code>&lt;input type=&quot;submit&quot;&gt;</code> — the code only tests <code>Len(Trim(url.Search))</code> to mean &quot;a search was submitted&quot;. There is no keyword box on that screen at all.</li><li><strong>Edit Columns.</strong> No column picker and no per-user column preference exist today. Built as a working prototype at Mark&#39;s direction.</li></ul><h3 id="progressive-columns" tabindex="-1">Progressive columns <a class="header-anchor" href="#progressive-columns" aria-label="Permalink to &quot;Progressive columns&quot;">​</a></h3><p>Every column carries a <code>tier</code>; tiers reveal as the TABLE widens (~180px steps, <code>@container</code> on the datatable&#39;s own inline size). Tier 1 is the row&#39;s identity and is always present. Measured: 5 columns at a 420px page, 22 at 2300px. At a 900px page the table is NARROWER than at 700px because the CC sidebar expands — a viewport query would show more columns in less space, which is the §4a failure mode exactly.</p><p>Edit Columns answers a different question from the tier: the tier decides whether there is ROOM, the picker whether a column is WANTED. A wanted column with no room still hides, and the panel says &quot;No room at this width&quot; rather than showing a tick against something invisible. That state is read back off the DOM (hidden <code>th</code> without <code>--off</code>) rather than by re-deriving the breakpoints in JS, which would drift from the stylesheet. The notes refresh from a <code>ResizeObserver</code> on the table, never <code>matchMedia</code>.</p><p>Order No. and Customer are locked in the picker — without them the table is a list of anonymous rows.</p><p>TODO(backend:Listing): column choices are in memory, like the saved views.</p><h2 id="sort-paging-and-column-widths-pass-4" tabindex="-1">Sort, paging and column widths (pass 4) <a class="header-anchor" href="#sort-paging-and-column-widths-pass-4" aria-label="Permalink to &quot;Sort, paging and column widths (pass 4)&quot;">​</a></h2><p>Display follows best practice, not the live screen — Mark, 2026-09-18: &quot;we dont need to follow what the old one does in terms of display. its just about the data.&quot; So the live <code>SELECT TOP 500</code> cap is deliberately NOT reproduced; paging here covers the whole result set.</p><p><strong>Order of operations: filter → sort → page.</strong> Paging first would sort only the visible slice; sorting first would page a list the filter is about to change. Any of the three resetting to page 1 where the old page number stops meaning anything (a new filter, a new search, a re-sort) — except rows-per-page, which recomputes the page so the first visible row stays on screen: 20 → 50 while reading page 4 should widen the view around where you were.</p><p><strong>Sorting</strong> is by VALUE, not rendered text — &quot;£1,000.00&quot; sorts before &quot;£9.95&quot; as a string. A value counts as numeric only if the whole of it is one, so &quot;£9.95&quot; and &quot;100412&quot; are numbers while &quot;EXT-0412&quot; and &quot;Paid Full&quot; are not. A second click on the same column reverses; a first click on a new one starts descending, which is what a date or a value is usually wanted by.</p><p><strong>Pagination is windowed</strong> — first, last, current ± 1, gaps elided, constant width so the control does not resize as you page: <code>1 2 3 4 … 14</code>, <code>1 … 6 7 8 … 14</code>, <code>1 … 11 12 13 14</code>.</p><p><strong>140 mock rows</strong>, generated deterministically from the ten seed rows, so paging and sorting are demonstrable and a screenshot stays reproducible.</p><h3 id="the-customer-column-squeeze-—-what-it-actually-was" tabindex="-1">The Customer column squeeze — what it actually was <a class="header-anchor" href="#the-customer-column-squeeze-—-what-it-actually-was" aria-label="Permalink to &quot;The Customer column squeeze — what it actually was&quot;">​</a></h3><p>Not a share-of-slack problem. <code>Table.css</code> sets <code>white-space: nowrap</code> on every <code>th</code> and <code>td</code> so a wide table scrolls rather than squashes. Right for a code or a date; wrong for &quot;Awaiting Payment Confirmation&quot;, which on its own made the table 1281px inside a 1055px container. Once the table overflows there is no slack at all, and every fluid column collapses to min-content — Customer rendering as &quot;Mari…&quot; was that, not a width share.</p><p>Three changes, in the order they mattered:</p><ol><li><strong><code>--snug</code></strong>: shrink-to-fit that unsets the nowrap, for the enumerated columns. Setting <code>width: 1%</code> alone did nothing, because the nowrap it was meant to escape comes from the Table component, not from Datatables.css. Payment Status 240px → 118px, Order Status 173 → 105.</li><li><strong>Customer is the only fluid column</strong> — everything else hugs or snugs, so it absorbs all the slack rather than an eighth of it.</li><li><strong>Tier thresholds re-tuned against measured widths</strong> rather than an even 180px step. Revealing a tier ~100px too early does not overflow the table, it silently starves Customer — which reads as a truncation bug rather than as a breakpoint being wrong, and is why these are measured.</li></ol><p>Measured after: no overflow at any width from 420px to 2600px, Customer between 169px and 569px, 5 columns up to 16.</p><p><strong>Known limitation:</strong> the tier is width-only, so switching columns OFF in Edit Columns does not promote the remaining ones into the freed space. Someone who wants Pro Forma ID on a 1500px screen cannot get it by turning others off. Making the reveal respond to how many columns are ON would fix it, and is a bigger change than it looks — worth doing deliberately rather than now.</p><h2 id="edit-columns-reordering-and-the-gap-pass-5" tabindex="-1">Edit Columns: reordering, and the gap (pass 5) <a class="header-anchor" href="#edit-columns-reordering-and-the-gap-pass-5" aria-label="Permalink to &quot;Edit Columns: reordering, and the gap (pass 5)&quot;">​</a></h2><h3 id="drag-to-reorder" tabindex="-1">Drag to reorder <a class="header-anchor" href="#drag-to-reorder" aria-label="Permalink to &quot;Drag to reorder&quot;">​</a></h3><p>Each row in the panel has a grip. The row is made <code>draggable</code> only while the pointer is on that grip, so the checkbox stays clickable and a stray drag on the label does not start a reorder.</p><p>Only the LABELLED columns move — the checkbox, spacer, edit and kebab columns are structure. The reorder happens on the labelled subset and is written back into the slots those columns occupied, so structure stays put.</p><p><strong>Reordering also re-tiers.</strong> A column&#39;s position IS its priority, so dragging one to the front is how you say &quot;show me this first&quot;. Without it, dragging a tier-9 column to the top would leave it hidden until 2600px, which reads as broken. Tiers are reassigned in pairs (<code>floor(i / 2) + 1</code>) to match the thresholds in Datatables.css, and the first two columns — whatever they now are — become the locked pair and are un-hidden if they had been switched off. This also answers the limitation flagged in pass 4: a column you want on a narrow screen is now reachable by dragging it up, rather than unreachable.</p><h3 id="the-gap-after-hiding-a-column" tabindex="-1">The gap after hiding a column <a class="header-anchor" href="#the-gap-after-hiding-a-column" aria-label="Permalink to &quot;The gap after hiding a column&quot;">​</a></h3><p>Customer was the only column that could grow, so ALL the freed width pooled in it: hiding one column stretched Customer from 267px to 372px, leaving a visible gap between the name and the next column.</p><p><code>max-inline-size</code> does <strong>not</strong> fix this — a max-width on a table cell is advisory under <code>table-layout: auto</code>, and the column stayed at 372. Two changes did:</p><ol><li>Customer gets a <strong>preferred</strong> width (<code>width: var(--ai-size-6)</code>), not <code>auto</code>. Auto layout treats <code>width</code> as a preference, so it still shrinks when space is tight but stops growing at 320px.</li><li>A <strong>spacer column</strong> before the actions absorbs whatever is left. Nothing real stretches, the columns stay closed up, and the row rules still run the full width of the table.</li></ol><p>The spacer is <code>role=&quot;presentation&quot;</code> with no accessible name, so screen readers do not announce an empty column.</p><h2 id="columns-are-part-of-the-view-pass-6" tabindex="-1">Columns are part of the view (pass 6) <a class="header-anchor" href="#columns-are-part-of-the-view-pass-6" aria-label="Permalink to &quot;Columns are part of the view (pass 6)&quot;">​</a></h2><p>Mark, 2026-09-18: editing the table &quot;constitutes a possible new view (workflow)&quot; — so a column change is a view change and must surface the same Save view CTA as a filter change.</p><p>The bar owns the CTA but must not learn what a column is, so it exposes <code>setViewExtra(string)</code>: an opaque value folded into the signature it already compares. The screen sends <code>columnState()</code> — the column key order plus the hidden set — on every visibility toggle and every reorder, and before re-baselining on a view switch.</p><p>Snapshots carry <code>columns</code> and <code>hiddenColumns</code> alongside the filters, COPIED rather than referenced: reordering rewrites each column&#39;s tier in place, so a stored reference would quietly follow the live table instead of preserving the layout as saved.</p><p>Verified round trip: hide a column → CTA appears; restore it → CTA goes (the signature is back at baseline, not merely &quot;something happened&quot;); reorder → CTA appears; save → CTA goes and the layout sticks; switch to All Orders → the original column order returns; switch back → the saved layout returns, CTA still hidden.</p><h2 id="cell-truncation-and-rhythm-pass-7" tabindex="-1">Cell truncation and rhythm (pass 7) <a class="header-anchor" href="#cell-truncation-and-rhythm-pass-7" aria-label="Permalink to &quot;Cell truncation and rhythm (pass 7)&quot;">​</a></h2><p>Designer, 2026-09-18: Customer too wide, long enumerated values should truncate, tighter line heights.</p><ul><li><strong>Customer&#39;s preferred width 320px → 240px.</strong></li><li><strong>Enumerated values truncate</strong> rather than wrap. The cap lives on an INNER span, not on the cell: <code>max-inline-size</code> on a <code>td</code> is advisory under <code>table-layout: auto</code>, so the column still sizes to max-content and nothing truncates. A block inside the cell has a max-content of its own, which is what actually caps the column. The full value stays in the <code>title</code>, and the kebab detail row deliberately does NOT truncate — it exists to show values in full.</li><li><strong>Line heights</strong>: <code>th</code> → <code>--ai-leading-xs</code> (16px), <code>td</code> → <code>--ai-leading-sm</code> (20px). Scoped to <code>.datatables--orders</code> rather than changed in <code>Table.css</code>, since the Seating Planner&#39;s tables use that component and were not part of this ask.</li></ul><h3 id="tier-thresholds-re-measured-again" tabindex="-1">Tier thresholds, re-measured (again) <a class="header-anchor" href="#tier-thresholds-re-measured-again" aria-label="Permalink to &quot;Tier thresholds, re-measured (again)&quot;">​</a></h3><p>Switching the enumerated columns from wrapping to truncating made them <strong>wider</strong>, not narrower — a 160px cap plus padding beats a two-line wrap — so the previous thresholds overflowed the table at every width past tier 4. That does not present as overflow so much as Customer silently collapsing back to 127px, which is the same symptom as the original bug and a good reason to measure rather than nudge.</p><p>Thresholds are now the measured cumulative width of every column up to that tier, relaxed by ~55px. That 55 is the dial between &quot;more columns&quot; and &quot;roomier Customer&quot; — the only number in the set that is a judgement rather than a measurement. At a 1500px page it is the difference between 9 columns with Customer at 199px and 7 columns with Customer at 240px.</p><p>Measured after: no overflow from 420px to 3800px; 6 columns at 420px, 23 at 3800px; Customer at its 240px preference everywhere except where space is genuinely tight.</p><h2 id="adaptive-column-fill-pass-8-—-replaces-the-tier-system" tabindex="-1">Adaptive column fill (pass 8) — replaces the tier system <a class="header-anchor" href="#adaptive-column-fill-pass-8-—-replaces-the-tier-system" aria-label="Permalink to &quot;Adaptive column fill (pass 8) — replaces the tier system&quot;">​</a></h2><p>Designer, 2026-09-18: dead space where another column would have fitted, and &quot;I really want to make this a strong feature of the new listing screens.&quot;</p><p>The tier steps could never deliver it. CSS can only reveal a column at a width chosen in advance, so between two steps the table always carried slack — ~400px on a 780px table, room for two more columns. Deciding what fits means knowing how wide each column WANTS to be, and only layout can answer that.</p><p>So the fit is measured:</p><ol><li><strong>Measure</strong> — show every column and put the TABLE at <code>width: max-content</code>, read each column&#39;s width, restore. One task, so nothing is painted.</li><li><strong>Fill</strong> — walk the columns in order, adding each while it still fits. Stop at the FIRST that does not rather than skipping to a narrower one further down: order is priority, and a table showing column 8 but not column 5 reads as a bug.</li><li><strong>Verify and correct</strong> — measure the result and drop the last column while the table is still over. A column&#39;s measured width is what it wants alone; beside different neighbours it can round a few pixels wider, which left one width 13px over. Checking the actual outcome beats padding the budget with a tolerance that would be wrong somewhere else.</li></ol><p>Driven by a <code>ResizeObserver</code> on the table body, never <code>matchMedia</code> — the CC sidebar changes this width with no window resize (CLAUDE.md §4a). This is the case §4a allows JS for; a container query genuinely cannot express it.</p><h3 id="two-traps-worth-recording" tabindex="-1">Two traps worth recording <a class="header-anchor" href="#two-traps-worth-recording" aria-label="Permalink to &quot;Two traps worth recording&quot;">​</a></h3><ul><li><strong>Measuring with every column shown gives MIN-content, not natural width.</strong> Twenty columns over-constrain a container-width table and each collapses: a column that renders at 125px measured 74px, so the fit let two more columns in than actually fit. The table has to go to <code>max-content</code> for the pass.</li><li><strong><code>width: 1%</code> on the enumerated columns had to go.</strong> Shrink-wrapping every column means any width the fit does not use must pool somewhere — in Customer, which ballooned, or in a spacer column, which read as a gap. They are now <code>auto</code> and share the leftover between them, so there is never a visible gap; their content is still capped by <code>__truncate</code>, so a long value cannot dictate the width. <strong>The spacer column is gone</strong>, and with it the trailing dead space.</li></ul><h3 id="result" tabindex="-1">Result <a class="header-anchor" href="#result" aria-label="Permalink to &quot;Result&quot;">​</a></h3><p>Gap is 0 at every width from 420px to 3800px: 2 columns at the narrowest, 20 at the widest, and the table always exactly fills its container.</p><p>Both column controls feed it. Hiding Order Total promotes Account into the freed space; dragging Invoices Sent to the top brings it on screen immediately and pushes the last one off. <code>tier</code> is gone from the config — <strong>order is priority</strong>, which makes the drag handle the control for &quot;show me this first&quot;.</p><h2 id="edit-columns-one-heading-not-a-note-per-row" tabindex="-1">Edit Columns: one heading, not a note per row <a class="header-anchor" href="#edit-columns-one-heading-not-a-note-per-row" aria-label="Permalink to &quot;Edit Columns: one heading, not a note per row&quot;">​</a></h2><p>The panel used to put &quot;No room at this width&quot; on every affected row — up to sixteen repetitions of the same sentence. Because the fit fills in ORDER, everything without room is the tail of the list, so a single heading at the cut says it once: above the line is on screen, below it is not.</p><p>It is the same <code>dropdown__label</code> as the &quot;Columns&quot; heading above it (designer, 2026-09-18).</p><p>The heading is PLACED into the list rather than the list being regrouped, so the rows keep their order — which matters, because they are draggable and dragging across the heading has to mean what it looks like it means.</p><p>Note a column switched OFF stays above the line: the heading is about room, not about the tick. Hiding a fitting column promotes the next one above the line, since the freed width is immediately re-fit.</p><h2 id="five-default-chips-for-every-screen" tabindex="-1">Five default chips, for every screen <a class="header-anchor" href="#five-default-chips-for-every-screen" aria-label="Permalink to &quot;Five default chips, for every screen&quot;">​</a></h2><p><code>DEFAULT_CHIPS = 5</code> in ListingScreen.js. A screen&#39;s config may list more filters as defaults — Orders lists the six its Simple Search form shows — and the extras move to the FRONT of the More Filters panel rather than being dropped. Order Owner is the first thing offered there, and adding it puts it straight back on the bar.</p><p>The split happens once at init, not at render time, so everything downstream — adding a filter, saving a view, restoring one — works on the real arrays and never has to know about the limit. The limit lives in the template rather than in <code>listing-data.js</code> because it applies to all ~400 screens.</p><h2 id="removing-a-filter-you-added" tabindex="-1">Removing a filter you added <a class="header-anchor" href="#removing-a-filter-you-added" aria-label="Permalink to &quot;Removing a filter you added&quot;">​</a></h2><p>Adding used to be one-way. The chip&#39;s face has no room for a remove control: FilterItem&#39;s leading slot holds <code>+</code> while empty and <code>×</code> once values are set, so a filter that is on the bar but has no value has nowhere to put one, and a second <code>×</code> on the right would fight the chevron (designer, 2026-09-18 — &quot;feels clunky&quot;). So removal lives in More Filters, which needs no new affordance:</p><p><strong>More Filters toggles.</strong> The panel is a stable CATALOGUE: a facet no longer leaves it when added, it turns solid with a check. Clicking it again takes the filter off the bar. Add and remove are the same gesture in the same place.</p><p>A second route — a <code>Remove filter</code> action under Apply inside the chip&#39;s own picker — was built and then taken out (designer, 2026-09-18: &quot;just keep more filters toggle for now&quot;). One way in and out is enough while the pattern settles; worth revisiting if removing turns out to be common enough that opening Add Filters each time grates.</p><p>Removing drops that filter&#39;s values with it and re-filters the table — verified: Order Status narrowed 20 rows to 9, removing it restored 20.</p><h3 id="model-change" tabindex="-1">Model change <a class="header-anchor" href="#model-change" aria-label="Permalink to &quot;Model change&quot;">​</a></h3><p><code>moreFilters</code> is a fixed catalogue and <code>config.added</code> holds the names the user has put on the bar, in order. <code>defaultFilters</code> — what the bar renders and what filtering looks names up in — is DERIVED from <code>baseFilters + added</code>. Saved views snapshot <code>added</code> rather than the arrays, since the arrays no longer move.</p><h3 id="flagged-for-figma" tabindex="-1">Flagged for Figma <a class="header-anchor" href="#flagged-for-figma" aria-label="Permalink to &quot;Flagged for Figma&quot;">​</a></h3><ul><li><strong>FilterItem has no &quot;already added&quot; state.</strong> Its slot is <code>+</code> or <code>×</code>, and neither means &quot;on the bar, click to remove&quot;. Implemented as the solid Default treatment with a check; it wants a real variant.</li></ul><h2 id="edit-columns-no-text-selection" tabindex="-1">Edit Columns: no text selection <a class="header-anchor" href="#edit-columns-no-text-selection" aria-label="Permalink to &quot;Edit Columns: no text selection&quot;">​</a></h2><p><code>user-select: none</code> on the whole <code>dropdown__panel--columns</code>. The rows are draggable, and a drag that starts anywhere but the grip otherwise sweeps a text selection across the list — which reads as the drag having failed rather than as having missed the handle (designer, 2026-09-18).</p><p>Scoped to this panel rather than set globally: nothing in it is worth copying, whereas a table of orders obviously is. Checkbox clicks and grip drags are unaffected — both re-verified after the change.</p><h2 id="date-filters" tabindex="-1">Date filters <a class="header-anchor" href="#date-filters" aria-label="Permalink to &quot;Date filters&quot;">​</a></h2><p>Order Date / Payment Date / Delivery Date use the real DatePicker. The screen now loads <code>DatePicker.css</code> + <code>DatePicker.js</code> and initialises pickers on <code>listing:rendered</code> alongside the other late-rendered components — without that the panel drew two inert readonly fields.</p><p><strong>Two date formats meet in the comparison</strong> and both are parsed rather than one pretending to be the other: rows carry ISO (<code>2026-09-28</code>, what a backend returns) and DatePicker writes what it displays (<code>28 Sep 2026</code>).</p><p><strong>Either end may be blank</strong> — an open-ended range is still a range. <code>valuesIn</code> keeps both positions, empty included, because collapsing <code>[&#39;&#39;, &#39;5 Sep 2026&#39;]</code> to one value would be read as &quot;from&quot; rather than &quot;up to&quot;. FilterItem drops the empty half from the chip&#39;s label by itself.</p><p>The same code serves the numeric ranges (Order No. Range, Price Range), which use the identical two-field widget — <code>toNumber</code> strips currency symbols and separators so &quot;£1,204.95&quot; compares.</p><p>Measured: 20–28 Sep gives 18 rows, all within range; &quot;up to 5 Sep&quot; gives 94, the latest being 2026-09-05.</p><h2 id="a-removed-facet-kept-looking-active" tabindex="-1">A removed facet kept looking active <a class="header-anchor" href="#a-removed-facet-kept-looking-active" aria-label="Permalink to &quot;A removed facet kept looking active&quot;">​</a></h2><p>Toggling a filter off in More Filters left its facet wearing FilterItem&#39;s <code>--open</code> palette — highlighted, but with no tick. It alternated, which is why it only appeared every other time: FilterItem toggles <code>--open</code> on every trigger click, so the add left it on and the remove cleared it, or the other way round depending on where the sequence started.</p><p><code>markFacet</code> now clears <code>--open</code> and <code>aria-expanded</code> on both paths. A facet is a BUTTON, not a chip with a picker of its own — it should never carry that state at all, whichever way it is being toggled.</p><p>Verified across four consecutive toggles: every removed state is identical to the initial one, class, background and border.</p><h2 id="more-filters-is-listed-alphabetically" tabindex="-1">More Filters is listed alphabetically <a class="header-anchor" href="#more-filters-is-listed-alphabetically" aria-label="Permalink to &quot;More Filters is listed alphabetically&quot;">​</a></h2><p>Forty-eight facets is a list you scan for a name, not one you read, so the panel sorts them (designer, 2026-09-18).</p><p>A COPY is sorted for display. <code>config.moreFilters</code> keeps its own order, which is provenance — the order the live screen declares its filters — and the added set is looked up by name, so the sort changes nothing but the reading order.</p><p>Side effect worth knowing: the overflow default (Order Owner, the sixth filter the live Simple Search shows) no longer heads the panel. It sits under O with everything else.</p><h2 id="catalogue-item-uses-the-multi-select-table" tabindex="-1">Catalogue Item uses the Multi Select Table <a class="header-anchor" href="#catalogue-item-uses-the-multi-select-table" aria-label="Permalink to &quot;Catalogue Item uses the Multi Select Table&quot;">​</a></h2><p>Designer, 2026-09-18: a flat checkbox list was the wrong widget. The live picker is paged and letter-filtered with its own Catalogue ID / Payment Method / Zone sub-filters, so an item needs more than a name to tell two apart.</p><p>Now <code>type: &#39;multi-select-table&#39;</code> — FilterDropdowns Type=Multi Select Table (3039:5624), verified against the Figma screenshot: 640px card, four facet chips (Name / Catalogue Group / Catalogue Item Code / Payment Method), a Datatables body with Name / Catalogue ID / Zone and a row-link column, Apply.</p><p>TODO(backend:Listing): the four sub-filter chips are visual only.</p><p><strong>The table&#39;s facet chips are not bar filters.</strong> They are FilterItems inside a picker, and FilterBar&#39;s add-filter click was scoped to any <code>.filter-bar__panel .filter-item</code> — so clicking &quot;Name&quot; in this card would have put a Name filter on the bar. Scoped to <code>.filter-dropdowns--more</code> now.</p><p><strong>Values come from <code>data-row-value</code></strong>, read before the generic checkbox branch: that branch looks for a <code>.checkbox__label-text</code>, which a table row does not have, and would have come back empty.</p><p>Measured: two rows selected gives &quot;Annual Membership, Quarterly Pass&quot; and 47 matching orders; select-all ticks all six and returns the full 140.</p>',181)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
